-- MP-0003: guarded editorial content import. Deploy portraits before applying.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='pas' and type='party') then raise exception 'MP-0003: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='perikatan-nasional' and type='alliance') then raise exception 'MP-0003: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('ku-abd-rahman-ku-ismail','nurul-amin-hamid','ahmad-saad-yahaya') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0003: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('kubang pasu','padang terap','pokok sena') and slug not in ('ku-abd-rahman-ku-ismail','nurul-amin-hamid','ahmad-saad-yahaya')) then raise exception 'MP-0003: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0003:%' and (m.source_type <> 'editorial' or e.slug not in ('ku-abd-rahman-ku-ismail','nurul-amin-hamid','ahmad-saad-yahaya') or m.import_key not like 'MP-0003:' || e.slug || ':%')) then raise exception 'MP-0003: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'ku-abd-rahman-ku-ismail','Ku Abd Rahman Ku Ismail','opposition','Member of the Dewan Rakyat','Kubang Pasu','Kedah','Ku Abd Rahman Ku Ismail represents Kubang Pasu, Kedah, in the Dewan Rakyat. Parliament lists affiliation with Perikatan Nasional (PN).','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4045','/portraits/ku-abd-rahman-ku-ismail.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P006.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4045"}, {"label": "Parliament · current Dewan Rakyat directory", "url": "https://www.parlimen.gov.my/ahli-dewan.html?uweb=dr"}]'::jsonb from public.entities parent where parent.slug='perikatan-nasional' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'nurul-amin-hamid','Nurul Amin Hamid','opposition','Member of the Dewan Rakyat','Padang Terap','Kedah','Nurul Amin Hamid represents Padang Terap, Kedah, in the Dewan Rakyat. A PAS member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4046','/portraits/nurul-amin-hamid.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P007.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4046"}, {"label": "PAS · current parliamentary representatives", "url": "https://pas.org.my/ahli-parlimen-pas-pru-ke-15/"}]'::jsonb from public.entities parent where parent.slug='pas' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'ahmad-saad-yahaya','Ahmad Saad @ Yahaya','opposition','Member of the Dewan Rakyat','Pokok Sena','Kedah','Ahmad Saad @ Yahaya represents Pokok Sena, Kedah, in the Dewan Rakyat. A PAS member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4047','/portraits/ahmad-saad-yahaya.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P008.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4047"}, {"label": "PAS · current parliamentary representatives", "url": "https://pas.org.my/ahli-parlimen-pas-pru-ke-15/"}]'::jsonb from public.entities parent where parent.slug='pas' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('ku-abd-rahman-ku-ismail','nurul-amin-hamid','ahmad-saad-yahaya') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0003: concurrent ownership or identity change'; end if; end $$;

commit;
